sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */

function evaluateProperty({api, helpers}) {

  var departing_on = new Date(api.data.dt_req.result.departing_on.displayValue).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
  var returning_on = new Date(api.data.dt_req.result.returning_on.displayValue).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });

  return [
  {
    "label": "Departing on",
    "value": {
      "type": "string",
      "value": departing_on
    }
  },
  {
    "label": "Returning on",
    "value": {
      "type": "string",
      "value": returning_on
    }
  }];
}
